<script>
// --- Prototype only: simulates fetching a page's basic details. ---
// A small built-in lookup for a few well-known sites, with a readable
// fallback derived from the domain for anything else.
const KNOWN = {
  "en.wikipedia.org/wiki/Bookmark_(digital)": { title: "Bookmark (digital) — Wikipedia", site: "Wikipedia" },
  "developer.mozilla.org/en-US/docs/Web/CSS/Flexbox": { title: "CSS Flexbox layout — MDN Web Docs", site: "MDN Web Docs" },
  "www.nytimes.com/2026/01/12/technology/reading-later.html": { title: "The Quiet Art of Reading Later", site: "The New York Times" },
  "github.com/rust-lang/rust": { title: "rust-lang/rust: The Rust programming language", site: "GitHub" }
};

function normalize(raw) {
  let u = raw.trim();
  if (!u) return null;
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  try { return new URL(u); } catch { return null; }
}
function lookupMeta(url) {
  const key = (url.host + url.pathname).replace(/\/$/, "");
  if (KNOWN[key]) return KNOWN[key];
  // Fallback: readable title from the last path segment or the domain.
  const seg = url.pathname.split("/").filter(Boolean).pop();
  const site = url.host.replace(/^www\./, "");
  const title = seg
    ? seg.replace(/[-_]/g, " ").replace(/\.\w+$/, "").replace(/\b\w/g, c => c.toUpperCase())
    : site;
  return { title, site };
}

const bookmarks = [];
const listEl = document.getElementById("list");
const urlEl = document.getElementById("url");
const btn = document.getElementById("save");
const hint = document.getElementById("hint");

function render() {
  if (bookmarks.length === 0) {
    listEl.innerHTML = '<div class="empty">No bookmarks yet. Paste a link above to save your first one.</div>';
    return;
  }
  listEl.innerHTML = "";
  bookmarks.forEach(b => {
    const card = document.createElement("div");
    card.className = "card";
    const titleHtml = b.filling
      ? '<span class="filling"><span class="dot"></span> Filling in details…</span>'
      : b.title;
    card.innerHTML =
      '<div class="title">' + titleHtml + '</div>' +
      '<div class="meta"><span class="fav">' + (b.site ? b.site[0].toUpperCase() : '?') + '</span>' +
      '<span>' + (b.filling ? '' : b.site) + '</span></div>' +
      '<a class="link" href="' + b.url + '" target="_blank" rel="noopener">' + b.url + '</a>';
    listEl.appendChild(card);
  });
}

function save() {
  const url = normalize(urlEl.value);
  if (!url) { hint.textContent = "That doesn't look like a link — please check it."; return; }
  const b = { url: url.href, title: "", site: "", filling: true };
  bookmarks.unshift(b);
  urlEl.value = "";
  hint.textContent = "Saved. Fetching its details for you…";
  render();
  // Simulate the brief auto-fill of basic details.
  setTimeout(() => {
    const meta = lookupMeta(url);
    b.title = meta.title; b.site = meta.site; b.filling = false;
    hint.textContent = "Details filled in automatically — nothing more to type.";
    render();
  }, 700);
}

btn.addEventListener("click", save);
urlEl.addEventListener("keydown", e => { if (e.key === "Enter") save(); });

render();
document.body.setAttribute("data-harness-ready", "true");
